import React from 'react';
import { connect } from 'react-redux';
import dynamic from 'next/dynamic';
import { QueryClient, QueryClientProvider } from 'react-query';
import { headTitlePrefix } from 'Utils/constants/variables'
import { changeUrl } from 'redux/actions/common';
import MainHead from 'components/IntegratePages/layout/dashboardMenu/head';
import Quote from '../components/features/setting/Quote';

const SharedSession = dynamic(
  import('components/shared/Sessions/SharedSession'),
  {
    loading: () => <></>,
    ssr: false,
  }
);

const CustomDashboard = dynamic(
  import('../components/features/CustomDashboard/SharedDashboard'),
  {
    loading: () => <></>,
    ssr: false,
  }
);

const DuplicateDomainAccess = dynamic(
  import('components/shared/DuplicateDomainAccess'),
  {
    loading: () => <></>,
    ssr: false,
  }
);

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: Infinity,
      retry: false,
    },
  },
});

const component = {
  quote: Quote,
  shareSession: SharedSession,
  shareDashboard: CustomDashboard,
  duplicateSignup: DuplicateDomainAccess
};
const headTitle = {
  quote: 'UXCam Order Form',
  shareSession: 'UXCam shared sessions',
  shareDashboard: 'UXCam shared dashboard',
  duplicateSignup: 'UXCam duplicate domain'
};
export const Public = ({ url, urlParam }) => {
  const parentType = url ? url.query.parentType : urlParam.parentType;
  const RenderComponent = component[parentType];
  const titleByParentType = headTitle[parentType];
  const titleByEnv = headTitlePrefix[process.env.APP_ENV];
  return (
    <QueryClientProvider client={queryClient}>
        <MainHead
          headTitle={`${titleByEnv}${titleByParentType}`}
          brainTreeScript="https://js.braintreegateway.com/web/dropin/1.32.1/js/dropin.min.js"
          chargebeeScript="https://js.chargebee.com/v2/chargebee.js"
        />
        <RenderComponent />
      </QueryClientProvider>
  );
};
Public.getInitialProps = ({ store, req }) => {
  store.dispatch(changeUrl(req.query));
};
const mapProps = ({ urlReducer }) => ({
  urlParam: urlReducer,
});
export default connect(mapProps, {})(Public);
