import React from 'react'
import { Form, Input } from 'antd';
import SignatureField from './SignaturePad'

const FormItem = Form.Item;
export const CustomerInformation = ({
  quoteDetails,
  setLoading,
  addNewPlan,
  _key,
  subscriptionId
}) => {
  const [form] = Form.useForm();
  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      addNewPlan(values)
      setLoading(true)
    } catch (err) { }
  }
  return (
    <>
      <h2>Customer Information</h2>
      <Form
        form={form}
        onFinish={handleSubmit}
        initialValues={{
          subscriptionId,
          key: _key,

        }}>
        <FormItem name='subscriptionId' hidden><Input type='hidden' /></FormItem>
        <FormItem name='key' hidden><Input type='hidden' /></FormItem>
        <FormItem name='paymentMethodNonce'><Input type='hidden' /></FormItem>
        <div className='form-group'>
          <Form.Item
            label="Full Name"
            name='fullName'
            rules={
              [
                {
                  required: true,
                  message: 'Fullname is required',
                  whitespace: true
                }
              ]
            }>
            <Input />
          </Form.Item>
        </div>
        <div className='form-group'>
          <Form.Item
            className='signature-box'
            label="Signature"
            name='signature'
            rules={
              [
                {
                  required: true,
                  message: 'Signature is required',
                  type: 'string'
                }
              ]
            }>
            <SignatureField
              handleSubmit={handleSubmit}
              form={form}
              quoteDetails={quoteDetails}
              clientToken={quoteDetails?.clientToken}
            />
          </Form.Item>
        </div>
      </Form>
    </>
  )
}
export default CustomerInformation;
