
import React from "react"

export const QuoteSubscriptionDetails = ({ quoteDetails }) => {
  const subscriptionDetail = quoteDetails?.subscriptionDetail
  const advancedRecordingAndAnalysis = quoteDetails?.advancedRecordingAndAnalysis
  const total = subscriptionDetail?.price
  const currency = total?.charAt(0)
  const totalAmount = parseFloat(total?.substring(1))
  const overagePrice = quoteDetails?.overagePricing
  const automaticRenewalText = quoteDetails?.issuedTo?.automaticRenewalText;
  return (
    <div>
      {(advancedRecordingAndAnalysis?.overage || advancedRecordingAndAnalysis?.webOverage) &&
      <div className='table-box subscription-table'>
        <h2>Overage Pricing Details</h2>
        <table>
          <tbody>
          {overagePrice?.session?.price > 0 &&
          <tr>
            <td>
              <strong>{`Price per extra ${overagePrice?.session?.per } sessions (mobile)`}</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>
                {`$ ${overagePrice?.session?.price}`}
              </strong>
            </td>
          </tr>}
          {overagePrice?.video?.price > 0 &&
          <tr>
            <td>
              <strong>{`Price per extra ${overagePrice?.video?.per } videos`}</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>
                {`$ ${overagePrice?.video?.price}`}
              </strong>
            </td>
          </tr>}
          {overagePrice?.event?.price > 0 &&
          <tr>
            <td>
              <strong>{`Price per extra ${overagePrice?.event?.per } events (mobile)`}</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>
                {`$ ${overagePrice?.event?.price}`}
              </strong>
            </td>
          </tr>}
          {overagePrice?.webSession?.price > 0 &&
          <tr>
            <td>
              <strong>{`Price per extra ${overagePrice?.webSession?.per } sessions (web)`}</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>
                {`$ ${overagePrice?.webSession?.price}`}
              </strong>
            </td>
          </tr>}
          {overagePrice?.webEvent?.price > 0 &&
          <tr>
            <td>
              <strong>{`Price per extra ${overagePrice?.webEvent?.per } events (web)`}</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>
                {`$ ${overagePrice?.webEvent?.price}`}
              </strong>
            </td>
          </tr>}
          </tbody>
        </table>
      </div>
      }
      <div className='table-box subscription-table'>
        <h2>Subscription Details</h2>
        <table>
          <tbody>
          <tr>
            <td>
              <strong>Effective Date</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>
                {subscriptionDetail?.effectiveDate}
              </strong>
            </td>
          </tr>
          <tr>
            <td>
              <strong>Contract Terms (months)</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>{subscriptionDetail?.initialContractTerms}</strong>
            </td>
          </tr>
          {(subscriptionDetail?.billingFrequencyNumber !== null && subscriptionDetail?.billingFrequencyNumber !== 0) &&
          <tr>
            <td>
              <strong>Billing Frequency (months)</strong>
            </td>
            <td style={{ width: '40%', textAlign: 'center' }}>
              <strong>{subscriptionDetail?.billingFrequencyNumber}</strong>
            </td>
          </tr>}
          {(subscriptionDetail?.totalRenewalCycles !== 1 && automaticRenewalText !== null) &&
            <tr>
              <td>
                <strong>Automatic Renewal</strong>
              </td>
              <td style={{ width: '40%', textAlign: 'left' }}>
                <p>
                 {automaticRenewalText}
                </p>
              </td>
            </tr>
          }

          {subscriptionDetail && subscriptionDetail.discount !== null && (
            <tr>
              <td>
                <strong>Discount included in total</strong>
              </td>
              <td>
                {subscriptionDetail?.discount}

              </td>
            </tr>
          )}
          <tr
            style={{
              backgroundColor: '#5D97FF',
              fontWeight: '500'
            }}
          >
            <td style={{ height: '40px', color: '#fff' }}>
              <strong>Payment Due</strong>
            </td>
            <td style={{ color: '#fff' }}>
            {!isNaN(totalAmount) && `${currency} ${totalAmount.toLocaleString()} `}
            </td>
          </tr>
          </tbody>
        </table>
      </div>
    </div>
  )
}

export default QuoteSubscriptionDetails
