import React, { useEffect, useState } from 'react'
import { useSelector, useDispatch } from 'react-redux';
import { Spin } from 'antd'
import { addNewPlan, fetchQuoteDetail } from 'redux/actions/quote'
import QuoteFormHeader from './QuoteFormHeader'
import QuotePlanDetails from './QuotePlanDetails'
import QuoteSubscriptionDetails from './QuoteSubscriptionDetails'
import GeneralInformation from './GeneralInformation'
import CustomerInformation from './CustomerInformation'

const OrderForm = () => {
  const dispatch = useDispatch();
  const { urlReducer: urlQuery,
    quoteReducer:quoteDetails
  } = useSelector(state => state);

  const addNewPlanFn = (data) => { dispatch(addNewPlan(data)); }

  const { subscriptionId, key } = urlQuery

  const [loading, setLoading] = useState(false)
  const coreFeatures = quoteDetails ? quoteDetails.coreFeatures : ''
  const isEmpty = obj => {
    for (const key in obj) {
      if (obj.hasOwnProperty(key)) return false
    }
    return true
  }
  useEffect(() => {
    dispatch(fetchQuoteDetail({ subscriptionId, key }))
  }, [subscriptionId])

  return (
    <Spin spinning={loading || isEmpty(quoteDetails)} size="large">
      <div className='order-form-wrapper'>
        <div className='container'>
          <QuoteFormHeader quoteDetails={quoteDetails} />
          <QuotePlanDetails
            quoteDetails={quoteDetails}
            coreFeatures={coreFeatures}
          />
          <QuoteSubscriptionDetails quoteDetails={quoteDetails} />
          <GeneralInformation quoteDetails={quoteDetails} />
          <CustomerInformation
            quoteDetails={quoteDetails}
            setLoading={setLoading}
            addNewPlan={addNewPlanFn}
            subscriptionId={subscriptionId}
            _key={key}
          />
        </div>
      </div>
    </Spin>
  )
}

export default OrderForm
