import React from 'react'
import _ from 'underscore'
import { CheckCircleFilled } from "@ant-design/icons";
import { Tag } from 'antd';
import { mappedObjFeature } from 'Utils/helpers/FeatureVariables'
import Feature from './Feature'

const defaultStyle = { width: '40%', textAlign: 'center' }
const defaultIcon = (
  <CheckCircleFilled style={{ color: '#32BF8A' }} />
)
export const CategoryComponent = ({ title, value }) => (
    <>
      {value && (title === 'Limits' || title === 'Support & Consulting' || Object.values(value).indexOf(1) > -1) &&
      <tr
        style={{
          backgroundColor: '#5D97FF',
          fontWeight: '500'
        }}
      >
        <td
         style={{
          color: '#fff',
        }}>{title}</td>
        <td style={defaultStyle} />
      </tr>
      }
      {_.map(value, (val, key) => val ? (
        <Feature key={key}
        planName={
        Object.keys(mappedObjFeature).includes(key)
          ? mappedObjFeature[key]
          : key
      }
        labelValue={title === 'Limits' ? val : val === 1 ? defaultIcon : Array.isArray(val) ? Array.isArray(val) && val.map(obj =>
        <Tag color='blue'>{obj} </Tag>) : val}
        />
        ) : null)}
    </>
  )

export default CategoryComponent
