import React from 'react';
import _ from 'underscore'
import CategoryComponent from './PlanFeatures/CategoryComponent';

export const QuotePlanDetails = ({ quoteDetails }) => {
  const {
    planLimit,
    coreFeatures,
    integrationAndDataExport,
    advanceSecurityAndAdministration,
    advancedRecordingAndAnalysis,
    supportAndConsulting,
    planName,
  } = quoteDetails

  const keyWithData = {
    Limits: planLimit,
    'Core Features': coreFeatures,
    'Advanced Recording & Analysis': advancedRecordingAndAnalysis,
    'Integrations & Data Export': integrationAndDataExport,
    'Advanced Security & Administration': advanceSecurityAndAdministration,
    'Support & Consulting': supportAndConsulting
  }
  return (
    <div>
      <div className='table-box'>
        <h2>Plan Details - {planName}</h2>
        <table>
          <tbody>
            {_.map(keyWithData, (value, key) => <CategoryComponent key={key} title={key} value={value} />)}
          </tbody>
        </table>
      </div>
    </div>
  )
}

export default QuotePlanDetails
