import { FETCH_QUOTE_DETAIL,QUOTE_ADD_PLAN,QUOTE_ADD_PLAN_FAILURE ,QUOTE_FETCH_FAILURE } from 'types'
import QuoteApi from 'services/quoteApi'
import SettingApi from 'services/settingApi'
import { getErrorHandle } from './common'

export const getQuoteDetail = data => ({
    type: FETCH_QUOTE_DETAIL,
    data
  })

export const getQuoteDetailFailure = error => ({
    type: QUOTE_FETCH_FAILURE,
    error,
  });

export const addQuotePlan = data => ({
    type: QUOTE_ADD_PLAN,
    data
  })
export const addQuotePlanFailure = error => ({
    type: QUOTE_ADD_PLAN_FAILURE,
    error
  })

export const fetchQuoteDetail = (formData) => (dispatch) =>
   QuoteApi.fetchQuoteDetailByIdentifier(formData).then(async (res) => {
    dispatch(getQuoteDetail(res.data.data))
    return res.data.data
  }).catch(error => {
    error && error.response && getErrorHandle(dispatch, null, error, 'dashboard')
    dispatch(getQuoteDetailFailure(error.response.data))
  } )
  // {
  //   error && error.response && getErrorHandle(dispatch, null, error.response, 'dashboard')
  // })



export const addNewPlan = (formData) => (dispatch) => QuoteApi.addPlan(formData).then(async (res) => {
    dispatch(addQuotePlan(res.data.data))
    return res.data.data
  }).catch(error => {
    dispatch(addQuotePlanFailure(error.response.data))
   // error && error.response && getErrorHandle(dispatch, null, error, 'dashboard')
  })

export const updateCreditCardPayment = (payload) => (dispatch) =>
  SettingApi.updatePaymentInfo(payload).then(async (res) => res.data.data ).catch(error => {
    error && error.response && getErrorHandle(dispatch, null, error, 'dashboard')
   // dispatch(getQuoteDetailFailure(error.response.data))
  } )
