import { axiosInstance } from './globalInstance'

class QuoteApi {
  static async fetchQuoteDetailByIdentifier (formData) {
    return await axiosInstance.get(`${process.env.API_URL  }/quote/${  formData.subscriptionId  }/${  formData.key}`, { withCredentials: true })
  }

  static async addPlan (formData) {
    return axiosInstance({
      method: 'post',
      url: `${process.env.API_URL  }/quote/${formData.subscriptionId}/${formData.key}/confirm-and-pay`,
      data: {
        fullName: formData.fullName,
        paymentMethodNonce: formData.paymentMethodNonce,
        signature: formData.signature
      },
      withCredentials: true
    })
  }
}

export default QuoteApi
