import React, { useEffect, useState } from 'react';
import { Button, message, Modal, Form, Input, Select } from 'antd';
import { useSelector } from 'react-redux';
import { Country, State } from 'country-state-city';

let _submitButtonEventCallback = null;
let _submitButton = null;

const NewPaymentModal = (props) => {
  const [form] = Form.useForm();
  const [nonce, setNonce] = useState();
  const [states, setStates] = useState([]);
  const [loading, setLoading] = useState(false);
  const { quoteReducer: quoteDetails } = useSelector((state) => state);
  const amount = quoteDetails?.subscriptionDetail?.price;

  const {
    newPlanVisible,
    handlePaymentCancel,
    handleSubmit,
    setNewPlanVisible,
  } = props;

  const countries = Country.getAllCountries();

  const handleCountryChange = (value) => {
    const statesVal = State.getStatesOfCountry(value);
    setStates(statesVal);
  };

  const callBrainTree = (type, container, submit) => {
    setTimeout(() => {
      braintree.dropin.create(
        {
          // Insert your tokenization key here
          authorization: props.clientToken,
          container,
          vaultManager: true,
          threeDSecure: true,
        },
        (createErr, _dropinInstance) => {
          if (createErr) {
            _dropinInstance.clearSelectedPaymentMethod();
            message.error(`BrainTree View Error--> ${createErr.message}`);
            handlePaymentCancel();
            return;
          }
          _submitButton = document.querySelector(submit);
          _submitButtonEventCallback = async function () {
            const values = await form.validateFields();
            if (values) {
              setLoading(true);
              _dropinInstance.requestPaymentMethod(
                {
                  threeDSecure: {
                    amount: parseFloat(amount?.substring(1)).toString(),
                    email: values?.email,
                    billingAddress: {
                      givenName: values?.firstName,
                      region: values?.region,
                      postalCode: values?.postalCode,
                      countryCodeAlpha2: values?.countryCode,
                    },
                  },
                },
                (requestPaymentMethodErr, payload) => {
                  if (requestPaymentMethodErr || !payload?.nonce) {
                    if (
                      requestPaymentMethodErr?._braintreeWebError?.details
                        ?.originalError?.details?.httpStatus === 422
                    ) {
                      message.error(
                        requestPaymentMethodErr?._braintreeWebError?.details
                          ?.originalError?.details?.originalError?.error
                          ?.message
                      );
                    } else {
                      requestPaymentMethodErr?.message &&
                        message.error(requestPaymentMethodErr.message);
                    }
                    if (payload && !payload?.liabilityShifted) {
                      setNewPlanVisible(false);
                    }
                    setLoading(false);
                    form.resetFields();
                    return;
                  }
                  setLoading(false);
                  setNonce(payload.nonce);
                }
              );
            }
          };

          _submitButton.addEventListener('click', _submitButtonEventCallback);
        }
      );
    }, 0);
  };

  const handlePaymentSubmit = () => {
    handleSubmit();
    handlePaymentCancel();
  };

  useEffect(() => {
    {
      newPlanVisible &&
        callBrainTree(
          'newPlanPayment',
          '#dropin-container-new-payment',
          '#new-payment'
        );
    }
  }, [newPlanVisible]);

  useEffect(() => {
    if (nonce !== undefined && nonce !== null) {
      props.form.setFieldsValue({ paymentMethodNonce: nonce });
    }
    if (nonce !== undefined) {
      handlePaymentSubmit();
    }
  }, [nonce]);

  return (
    <div>
      <Modal
        title="Make Payment"
        visible={newPlanVisible}
        onCancel={!loading ? handlePaymentCancel : null}
        footer={null}
        width={640}
      >
        <div>
          <Form className="two-col-form" form={form}>
            <Form.Item
              label="Name"
              name="name"
              rules={[
                {
                  required: true,
                  message: 'Please input your name!',
                  whitespace: true,
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              label="Email"
              name="email"
              rules={[
                {
                  required: true,
                  message: 'Please input your email address!',
                  whitespace: true,
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              label="Country"
              name="countryCode"
              rules={[
                {
                  required: true,
                },
              ]}
            >
              <Select
                getPopupContainer={(node) => node.parentNode}
                showSearch
                placeholder="Search to select"
                optionFilterProp="children"
                filterOption={(input, option) =>
                  option.children.toLowerCase().indexOf(input.toLowerCase()) >=
                  0
                }
                onChange={handleCountryChange}
              >
                {countries.map((country) => (
                  <Select.Option value={country.isoCode} key={country?.isoCode}>
                    {country.name}
                  </Select.Option>
                ))}
              </Select>
            </Form.Item>

            <Form.Item label="State/Region" name="region">
              <Select
                getPopupContainer={(node) => node.parentNode}
                showSearch
                placeholder="Search to select"
                optionFilterProp="children"
                filterOption={(input, option) =>
                  option.children.toLowerCase().indexOf(input.toLowerCase()) >=
                  0
                }
              >
                {states.map((state) => (
                  <Select.Option key={state.isoCode} value={state.isoCode}>
                    {state.name}
                  </Select.Option>
                ))}
              </Select>
            </Form.Item>
            <Form.Item label="Postal code" name="postalCode">
              <Input />
            </Form.Item>
            <div style={{ paddingBottom: 15 }} id="dropin-wrapper">
              <div id="dropin-container-new-payment" />
            </div>
            <div className="form-group" style={{ textAlign: 'center' }}>
              <Button type="gradient" id="new-payment" className="btn-pay">
                Pay Now
              </Button>
            </div>
          </Form>
        </div>
      </Modal>
    </div>
  );
};

export default NewPaymentModal;
